/* Procedure structure for procedure `SpCheckUsernameExists_Sababan` */

/*!50003 DROP PROCEDURE IF EXISTS  `SpCheckUsernameExists_Sababan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SpCheckUsernameExists_Sababan`(
    IN p_username VARCHAR(255),
    OUT p_exists BOOLEAN
)
BEGIN
    SELECT CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END 
    INTO p_exists
    FROM credential 
    WHERE cre_username = p_username;
END */$$
DELIMITER ;

/* Procedure structure for procedure `SpCreateCredential_Herminado` */

/*!50003 DROP PROCEDURE IF EXISTS  `SpCreateCredential_Herminado` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SpCreateCredential_Herminado`(
    IN p_user_id INT,
    IN p_username VARCHAR(255),
    IN p_password_hash VARCHAR(255),
    OUT p_success BOOLEAN
)
BEGIN
    VALUES (p_user_id, p_username, p_password_hash, 1);
    SET p_success = TRUE;
END */$$
DELIMITER ;

/* Procedure structure for procedure `SpCreateStore_Sababan` */

/*!50003 DROP PROCEDURE IF EXISTS  `SpCreateStore_Sababan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SpCreateStore_Sababan`(
    IN p_store_name VARCHAR(255),
    OUT p_store_id INT
)
BEGIN
    SET p_store_id = LAST_INSERT_ID();
END */$$
DELIMITER ;

/* Procedure structure for procedure `SpCreateUser_Herminado` */

/*!50003 DROP PROCEDURE IF EXISTS  `SpCreateUser_Herminado` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SpCreateUser_Herminado`(
    IN p_store_id INT,
    IN p_barangay_id INT,
    IN p_first_name VARCHAR(255),
    IN p_middle_name VARCHAR(255),
    IN p_suffix_name VARCHAR(255),
    IN p_last_name VARCHAR(255),
    OUT p_user_id INT
)
BEGIN
    VALUES (p_store_id, p_barangay_id, p_first_name, p_middle_name, p_suffix_name, p_last_name);
    SET p_user_id = LAST_INSERT_ID();
END */$$
DELIMITER ;

/* Procedure structure for procedure `SpGetUserByUsername_Sababan` */

/*!50003 DROP PROCEDURE IF EXISTS  `SpGetUserByUsername_Sababan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SpGetUserByUsername_Sababan`(
    IN p_username VARCHAR(255)
)
BEGIN
    SELECT 
        u.users_id,
        u.store_id,
        u.users_role,
        u.users_fname,
        u.users_mname,
        u.users_sname,
        u.users_lname,
        u.barangay_id,
        b.brgy_name,
        m.mun_name,
        p.prov_name,
        c.cre_username,
        c.cre_password
    FROM users u
    INNER JOIN credential c ON u.users_id = c.users_id
    LEFT JOIN barangay b ON u.barangay_id = b.brgy_id
    LEFT JOIN municipality m ON b.mun_id = m.mun_id
    LEFT JOIN province p ON m.prov_id = p.prov_id
    WHERE c.cre_username = p_username;
END */$$
DELIMITER ;

/* Procedure structure for procedure `SpSelectBrgyByMuni_Fabia` */

/*!50003 DROP PROCEDURE IF EXISTS  `SpSelectBrgyByMuni_Fabia` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SpSelectBrgyByMuni_Fabia`(
    IN p_municipality_id INT
)
BEGIN
    SELECT brgy_id, brgy_name 
    FROM barangay 
    WHERE mun_id = p_municipality_id 
    ORDER BY brgy_name;
END */$$
DELIMITER ;

/* Procedure structure for procedure `SpSelectMuniByPro_Lago` */

/*!50003 DROP PROCEDURE IF EXISTS  `SpSelectMuniByPro_Lago` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SpSelectMuniByPro_Lago`(
    IN p_province_id INT
)
BEGIN
    SELECT mun_id, mun_name
    FROM municipality
    WHERE prov_id = p_province_id
    ORDER BY mun_name;
END */$$
DELIMITER ;

/* Procedure structure for procedure `SpSelectProducts_valenzuela` */

/*!50003 DROP PROCEDURE IF EXISTS  `SpSelectProducts_valenzuela` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SpSelectProducts_valenzuela`(
    IN p_store_id INT
)
BEGIN
    IF p_store_id = 0 THEN
        SELECT 
            p.product_id,
            p.product_name,
            p.product_quantity,
            p.product_date_added,
            s.store_name
        FROM product p
        LEFT JOIN store s ON p.store_id = s.store_id
        ORDER BY p.product_id DESC;
    ELSE
        SELECT 
            p.product_id,
            p.product_name,
            p.product_quantity,
            p.product_date_added,
            s.store_name
        FROM product p
        LEFT JOIN store s ON p.store_id = s.store_id
        WHERE p.store_id = p_store_id
        ORDER BY p.product_id DESC;
    END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `SpSelectProv_Maramag` */

/*!50003 DROP PROCEDURE IF EXISTS  `SpSelectProv_Maramag` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SpSelectProv_Maramag`()
BEGIN
    SELECT prov_id, prov_name
    FROM province
    ORDER BY prov_name;
END */$$
DELIMITER ;

/* Procedure structure for procedure `SpSelectStores_Fabia` */

/*!50003 DROP PROCEDURE IF EXISTS  `SpSelectStores_Fabia` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SpSelectStores_Fabia`()
BEGIN
    SELECT store_id, store_name
    FROM store
    ORDER BY store_id;
END */$$
DELIMITER ;

